#!/usr/bin/env bash\nset -e\n\n# Build the Docker image (quietly)\ndocker build -t pantry-suggester . > /dev/null\n\n# Create a temporary sample pantry CSV\ncat > sample.csv <<'EOF'\nbread,2\npeanut butter,1\napple,3\nbanana,2\ncarrot,5\npotato,4\nwater,1\nEOF\n\n# Run the container and capture output\noutput=$(docker run --rm -v "$(pwd)/sample.csv":/data/pantry.csv pantry-suggester /data/pantry.csv)\n\n# Expected output fragments\nexpected1="You can make:"\nexpected2="- Peanut Butter Sandwich"\nexpected3="- Fruit Salad"\nexpected4="- Veggie Soup"\n\n# Verify each expected fragment is present\necho "$output" | grep -F "$expected1" > /dev/null\necho "$output" | grep -F "$expected2" > /dev/null\necho "$output" | grep -F "$expected3" > /dev/null\necho "$output" | grep -F "$expected4" > /dev/null\n\necho "All tests passed."
